Theorem head : PMA.locale_ctor_spec L ar HI ->
  forall (fx : FPState) R0 M0 model0 K LB FF LK0 Aw0 cr sp r fb oa str sm,
    PMARS.pre L ar HI R0 M0 model0 K LB FF LK0 Aw0 cr sp r fb oa str sm ->
    (forall (fx1 : FPState) R1 M1 model1 LK1 Aw1, PMARS.rmid1 L ar HI R0 M0 model0 LB FF LK0 Aw0 cr sp fb R1 M1 model1 LK1 Aw1 ->
        srealizes RSEGS SCFG (PMSPA.cfg RSEGS (fx:=fx1) R1 0xb1e28 M1 model1) K) ->
    srealizes RSEGS SCFG (PMSPA.cfg RSEGS (fx:=fx) R0 0xb153c M0 model0) K.
Proof.
